// Diagnostic candidate discovery only. No wire field, verifier premise,
// receipt, or production source consumes this prototype.
func prototypeOriginalHelperTransfers(p *project, fn *ast.Node, calls []typefacts.ImplementationCall) []typefacts.Location {
 if implementationCompletionForm(fn) != typefacts.CompletionPlain || mentionsArgumentsOrEval(ast.GetSourceFileOfNode(fn).AsNode()) { return nil }
 nested := false
 var scan func(*ast.Node)
 scan = func(n *ast.Node) {
  if n == nil { return }
  if isCallableDeclaration(n) { nested = true; return }
  n.ForEachChild(func(c *ast.Node) bool { scan(c); return nested })
 }
 scan(fn.Body())
 symbols := map[int]*ast.Symbol{}
 seen := map[*ast.Symbol]bool{}
 for i,param := range fn.Parameters() {
  if param.Name() == nil || !ast.IsIdentifier(param.Name()) || param.AsParameterDeclaration().DotDotDotToken != nil { return nil }
  scan(param.Initializer())
  symbol := p.canonicalSymbol(p.formChecker().GetSymbolAtLocation(param.Name()))
  if symbol == nil || len(symbol.Declarations) != 1 || seen[symbol] { return nil }
  seen[symbol] = true; symbols[i] = symbol
 }
 if nested { return nil }
 cutoffs := p.positionalOriginalInputCutoffsLocked(fn.Body(),symbols,p.formChecker())
 // Initializers execute before the body. Their explicit writes must join the
 // census even when they belong to a different parameter.
 for _,param := range fn.Parameters() {
  if param.Initializer() == nil { continue }
  for index,cutoff := range p.positionalOriginalInputCutoffsLocked(param.Initializer(),symbols,p.formChecker()) {
   if old,ok := cutoffs[index]; !ok || cutoff < old { cutoffs[index] = cutoff }
  }
 }
 admissible := map[typefacts.Location]bool{}
 for _,call := range calls {
  if !call.Captured && call.Reach != typefacts.Unreachable { admissible[call.Location] = true }
 }
 var found []typefacts.Location
 var walk func(*ast.Node)
 walk = func(n *ast.Node) {
  if n == nil { return }
  if ast.IsCallExpression(n) && admissible[nodeLocation(n)] {
   callee := p.formRuntimeCalleeDeclarationLocked(n)
   name := identityPreservingUnwrap(n.Expression())
   if callee != nil && ast.GetSourceFileOfNode(callee) == ast.GetSourceFileOfNode(fn) && ast.IsIdentifier(name) {
    symbol := p.canonicalSymbol(p.formChecker().GetSymbolAtLocation(name))
    if symbol != nil && len(symbol.Declarations) == 1 && !p.symbolIsAssignedLocked(symbol, symbol.Declarations[0]) {
     for slot,arg := range n.Arguments() {
      if ast.IsSpreadElement(arg) { break }
      arg = identityPreservingUnwrap(arg)
      if arg == nil || !ast.IsIdentifier(arg) { continue }
      actual := p.canonicalSymbol(p.formChecker().GetSymbolAtLocation(arg))
      for index,wanted := range symbols {
       if actual != wanted || fn.Parameters()[index].Initializer() != nil { continue }
       if cutoff,written := cutoffs[index]; written && nodeLocation(arg).EndByte > cutoff { continue }
       if callee.Name() == nil { continue }
       target:=nodeLocation(callee.Name())
       helper,err:=p.ExportValueTranscripts(context.Background(),[]typefacts.ExportValueDemand{{Location:target,ImplementationLocation:&target}})
       if err!=nil || len(helper.Transcripts)!=1 || helper.Transcripts[0].Implementation==nil { continue }
       body:=helper.Transcripts[0].Implementation
       original:=false
       for _,binding:=range body.UnwrittenParameters { if binding.ParameterIndex==slot { original=true } }
       if !original { continue }
       read:=false
       for _,call:=range body.Calls {
        if call.Captured || call.Reach==typefacts.Unreachable || call.CalleeParameter==nil { continue }
        receiver:=call.CalleeParameter
        if receiver.ParameterIndex==slot && len(receiver.Path)==1 && receiver.Path[0].Property=="slice" { read=true }
       }
       if !read { continue }
       found = append(found,nodeLocation(arg))
      }
     }
    }
   }
  }
  n.ForEachChild(func(c *ast.Node) bool { walk(c); return false })
 }
 walk(fn.Body())
 return found
}

func TestPrototypeOriginalHelperTransfers(t *testing.T) {
 cases := []struct{name,source,export string; want int}{
  {"beforeStore",`function read(key: string) { return key.slice(0); } export function check(input: string) { read(input); input="local"; read(input); }`,"check",1},
  {"afterStore",`function read(key: string) { return key.slice(0); } export function check(input: string) { input="local"; read(input); }`,"check",0},
  {"siblingStore",`function read(key: string) { return key.slice(0); } export function check(input: string, other=(input="local")) { read(input); }`,"check",0},
  {"siblingLiteral",`function read(key: string) { return key.slice(0); } export function check(input: string, other="local") { read(input); input="local"; }`,"check",1},
  {"loopStore",`function read(key: string) { return key.slice(0); } export function check(input: string) { for(let i=0;i<2;i++){ read(input); input="local"; } }`,"check",0},
  {"calleeStore",`function read(key: string) { return key.slice(0); } read=()=>"local"; export function check(input: string) { read(input); }`,"check",0},
  {"capturedStore",`function read(key: string) { return key.slice(0); } export function check(input: string, other=()=>input="local") { read(input); }`,"check",0},
  {"deadCall",`function read(key: string) { return key.slice(0); } export function check(input: string) { if(false)read(input); }`,"check",0},
  {"spread",`function read(...key: string[]) { return key.slice(0); } export function check(input: string) { read(...[], input); }`,"check",0},
  {"varStore",`function read(key: string) { return key.slice(0); } export function check(input: string) { var input="local"; read(input); }`,"check",0},
  {"varStoreThenAssignment",`function read(key: string) { return key.slice(0); } export function check(input: string) { var input="local"; read(input); input="later"; }`,"check",0},
  {"moduleEval",`function read(key: string) { return key.slice(0); } eval("read=()=>null"); export function check(input: string) { read(input); }`,"check",0},
  {"helperStore",`function read(key: string) { key="local"; return key.slice(0); } export function check(input: string) { read(input); }`,"check",0},
  {"wrongMember",`function read(key: string) { return key.trim(); } export function check(input: string) { read(input); }`,"check",0},
  {"wrongSlot",`function read(local: string,key: string) { return key.slice(0); } export function check(input: string) { read(input,"local"); }`,"check",0},
 }
 bytes,err := os.ReadFile("/private/var/folders/y3/kgy_4tp56z717bf03m_v9cc00000gn/T/solid-checker-ecosystem-30IQvH/node_modules/fractional-indexing/src/index.js")
 if err != nil { t.Fatal(err) }
 cases = append(cases,struct{name,source,export string; want int}{"publishedFractional",string(bytes),"generateKeyBetween",2})
 for _,tc := range cases { t.Run(tc.name,func(t *testing.T){
  dir:=t.TempDir();source:=tc.source+"\nvoid "+tc.export+";\n"
  filename:="facts.ts"
  if tc.name=="publishedFractional" { filename="facts.js" }
  writeInvocationProject(t,dir,map[string]string{filename:source})
  if tc.name=="publishedFractional" {
   if err:=os.WriteFile(filepath.Join(dir,"tsconfig.json"),[]byte(`{"compilerOptions":{"strict":true,"allowJs":true,"checkJs":true,"module":"esnext","target":"esnext","moduleResolution":"bundler"},"include":["*.js"]}`),0600);err!=nil{t.Fatal(err)}
  }
  opened,err:=OpenProject(context.Background(),filepath.Join(dir,"tsconfig.json"),nil);if err!=nil{t.Fatal(err)};defer opened.Close()
  p:=opened.(*project);path:=filepath.Join(dir,filename)
  start,impl:=strings.LastIndex(source,tc.export),strings.Index(source,"function "+tc.export+"(")+len("function ")
  answer,err:=p.ExportValueTranscripts(context.Background(),[]typefacts.ExportValueDemand{{Location:typefacts.Location{Path:path,StartByte:start,EndByte:start+len(tc.export)},ImplementationLocation:&typefacts.Location{Path:path,StartByte:impl,EndByte:impl+len(tc.export)}}})
  if err!=nil{t.Fatal(err)};if answer.Transcripts[0].Implementation==nil{t.Fatal("no implementation")}
  cursor:=semanticNodeCursor{sourceFile:p.program.GetSourceFile(path)}
  name:=cursor.exactExpressionAt(impl,impl+len(tc.export));if name==nil{t.Fatal("no declaration name")}
  fn:=name.Parent
  found:=prototypeOriginalHelperTransfers(p,fn,answer.Transcripts[0].Implementation.Calls)
  if len(found)!=tc.want{t.Fatalf("candidate arguments=%+v, want %d",found,tc.want)}
 }) }
}

func TestExistingOriginalReadAfterParameterRedeclaration(t *testing.T) {
 source:=`export function check(input: string) { var input="local"; const first=input.slice(0); input="later"; return first; }`+"\nvoid check;\n"
 dir:=t.TempDir();writeInvocationProject(t,dir,map[string]string{"facts.ts":source})
 opened,err:=OpenProject(context.Background(),filepath.Join(dir,"tsconfig.json"),nil);if err!=nil{t.Fatal(err)};defer opened.Close()
 path:=filepath.Join(dir,"facts.ts");start,impl:=strings.LastIndex(source,"check"),strings.Index(source,"check(")
 answer,err:=opened.(typefacts.ExportValueAnalyzer).ExportValueTranscripts(context.Background(),[]typefacts.ExportValueDemand{{Location:typefacts.Location{Path:path,StartByte:start,EndByte:start+5},ImplementationLocation:&typefacts.Location{Path:path,StartByte:impl,EndByte:impl+5}}})
 if err!=nil{t.Fatal(err)}
 body:=answer.Transcripts[0].Implementation;if body==nil{t.Fatal("missing implementation")}
 if len(body.InitialParameterReads)!=0{t.Fatalf("read follows a redeclaration store: %+v",body.InitialParameterReads)}
}

package tsgo

import (
	"github.com/microsoft/typescript-go/shim/ast"
	"github.com/yumemi-thomas/solid-checker/apps/solid-typefacts/internal/typefacts"
)

// This is an opening-prefix proof, not a general control-flow analysis. Each
// admitted statement is a const declaration with simple names and only plain
// identifier/property initializers. At the first plain parameter assignment,
// also admit only its leading RHS call receiver, evaluated before the store.
// Stop before every other statement or effect.
// Getters can run user code, so also exclude every nested callable, arguments,
// eval and parameter initializer: none can then expose or mutate these lexical
// parameter bindings before the recorded use. Later direct assignments do not
// retroactively replace a value that this prefix has already read.
func (p *project) initialParameterReadsLocked(implementation *ast.Node, signature *typefacts.SelectedSignature, demand typefacts.Location, uses []typefacts.ParameterUse) []typefacts.InitialParameterRead {
	if signature == nil || implementationCompletionForm(implementation) != typefacts.CompletionPlain || mentionsArgumentsOrEval(implementation) {
		return nil
	}
	body := implementation.Body()
	if body == nil || !ast.IsBlock(body) {
		return nil
	}
	nested := false
	var scan func(*ast.Node)
	scan = func(node *ast.Node) {
		if isCallableDeclaration(node) {
			nested = true
			return
		}
		node.ForEachChild(func(child *ast.Node) bool { scan(child); return nested })
	}
	scan(body)
	if nested {
		return nil
	}
	names := make(map[string]bool)
	bindings := make(map[int]typefacts.Location)
	// The file's own checker: a premise twin's file (ADR 0038) was bound by the
	// twin program, every other file by the accepted one.
	fileChecker := p.checker
	if sourceFile := ast.GetSourceFileOfNode(implementation); p.formTwin != nil && sourceFile == p.formTwin.file {
		fileChecker = p.formTwin.checker
	}
	symbols := make(map[int]*ast.Symbol)
	for index, parameter := range implementation.Parameters() {
		name := parameter.Name()
		if name == nil || !ast.IsIdentifier(name) || parameter.Initializer() != nil || parameter.AsParameterDeclaration().DotDotDotToken != nil || names[name.Text()] {
			return nil
		}
		names[name.Text()] = true
		if index >= len(signature.Parameters) {
			return nil
		}
		selected := signature.Parameters[index]
		location := nodeLocation(name)
		if selected.Index != index || selected.Rest || selected.Defaulted || selected.Declaration == nil || selected.Declaration.Location != location || location.Path != demand.Path {
			return nil
		}
		bindings[index] = location
		symbol := p.canonicalSymbol(fileChecker.GetSymbolAtLocation(name))
		if symbol == nil || len(symbol.Declarations) != 1 {
			return nil
		}
		symbols[index] = symbol
	}
	cutoffs := p.positionalOriginalInputCutoffsLocked(body, symbols, fileChecker)
	defaults := p.undefinedParameterDefaultsLocked(body, symbols, fileChecker)
	prefixEnd := 0
	var firstReceiver *ast.Node
	firstIterationOnly := false
	for _, statement := range body.AsBlock().Statements.Nodes {
		if nodeKindName(statement) != "VariableStatement" {
			if loopBody := initialIterationBody(statement, names); loopBody != nil {
				statement = loopBody
				firstIterationOnly = true
			}
			// A plain binding assignment evaluates its RHS before storing it.
			// Only follow the leading callee/receiver chain, never arguments or
			// subsequent expressions, which may already observe a replacement.
			if nodeKindName(statement) == "ExpressionStatement" {
				expression := identityPreservingUnwrap(statement.Expression())
				if expression != nil && ast.IsBinaryExpression(expression) {
					assignment := expression.AsBinaryExpression()
					if assignment.OperatorToken.Kind == ast.KindEqualsToken && ast.IsIdentifier(assignment.Left) && names[assignment.Left.Text()] {
						firstReceiver = initialCallReceiver(assignment.Right)
					}
				}
			}
			break
		}
		var list *ast.Node
		statement.ForEachChild(func(child *ast.Node) bool {
			if nodeKindName(child) == "VariableDeclarationList" {
				list = child
			}
			return false
		})
		if list == nil {
			break
		}
		safe := true
		for _, declaration := range list.AsVariableDeclarationList().Declarations.Nodes {
			name := declaration.Name()
			if !ast.IsVarConst(declaration) || name == nil || !ast.IsIdentifier(name) || names[name.Text()] || !initialReadExpression(declaration.Initializer()) {
				safe = false
				break
			}
		}
		if !safe {
			break
		}
		prefixEnd = nodeLocation(statement).EndByte
	}
	var reads []typefacts.InitialParameterRead
	for _, use := range uses {
		declaration, ok := bindings[use.ParameterIndex]
		if !ok || len(use.BindingPath) != 0 || use.Kind != typefacts.ParameterUsePropertyAccess ||
			use.Captured || use.Alias || use.Location.Path != demand.Path {
			continue
		}
		inPrefix := use.Location.StartByte >= nodeLocation(body).StartByte && use.Location.EndByte <= prefixEnd
		isFirstReceiver := firstReceiver != nil && use.Location == nodeLocation(firstReceiver)
		conditional := isFirstReceiver && firstIterationOnly
		if (use.Reach == typefacts.Reachable || conditional && use.Reach == typefacts.ReachUnknown) && (inPrefix || isFirstReceiver) {
			reads = append(reads, typefacts.InitialParameterRead{ParameterIndex: use.ParameterIndex, Declaration: declaration, Use: use.Location, FirstIterationOnly: conditional})
			continue
		}
		// ADR 0069. A read this body's own stores cannot precede. The premise
		// is order, and it is about this exact use: a prefix row says some read
		// of the parameter saw the caller's value, while this one says *this*
		// read did. It is marked so, because only a consumer that binds the use
		// to its own operation may take the weaker reading. A parameter with no
		// cutoff is unwritten here, and `unwrittenParameterBindingsLocked`
		// states that stronger fact instead.
		// Reachable only. The client binds every row to exactly one census use
		// under that same filter, so a row it cannot bind is not a weaker
		// premise — it is an invalid transcript, and the export is lost rather
		// than refused.
		cutoff, written := cutoffs[use.ParameterIndex]
		if !written || use.Location.EndByte > cutoff || use.Reach != typefacts.Reachable {
			if fallback, ok := defaults[use.ParameterIndex]; ok &&
				use.Location == fallback.use && use.Reach == typefacts.Reachable {
				reads = append(reads, typefacts.InitialParameterRead{
					ParameterIndex: use.ParameterIndex, Declaration: declaration,
					Use: use.Location, UndefinedDefault: fallback.fact,
				})
			}
			continue
		}
		reads = append(reads, typefacts.InitialParameterRead{
			ParameterIndex: use.ParameterIndex,
			Declaration:    declaration,
			Use:            use.Location,
			Positional:     true,
		})
	}
	return reads
}

// Enter only one synchronous for-of, optionally guarded by a plain property
// expression. Its header cannot assign or shadow any parameter. With the
// enclosing no-closure/no-eval exclusions, external iterator code cannot mutate
// these lexical bindings. Only the first body's leading assignment is used;
// subsequent iterations expressly do not retain the caller-origin premise.
func initialIterationBody(node *ast.Node, parameters map[string]bool) *ast.Node {
	if nodeKindName(node) == "IfStatement" {
		branch := node.AsIfStatement()
		if branch.ElseStatement != nil || !initialReadExpression(branch.Expression) {
			return nil
		}
		node = branch.ThenStatement
	}
	if nodeKindName(node) != "ForOfStatement" {
		return nil
	}
	loop := node.AsForInOrOfStatement()
	if loop.AwaitModifier != nil || !initialIterationExpression(loop.Expression) || loop.Initializer == nil || nodeKindName(loop.Initializer) != "VariableDeclarationList" {
		return nil
	}
	declarations := loop.Initializer.AsVariableDeclarationList().Declarations.Nodes
	if len(declarations) != 1 || !ast.IsVarConst(declarations[0]) || declarations[0].Initializer() != nil || !initialIterationBinding(declarations[0].Name(), parameters) {
		return nil
	}
	body := loop.Statement
	if ast.IsBlock(body) {
		statements := body.AsBlock().Statements.Nodes
		if len(statements) == 0 {
			return nil
		}
		body = statements[0]
	}
	return body
}

func initialIterationBinding(node *ast.Node, parameters map[string]bool) bool {
	if node == nil {
		return false
	}
	if ast.IsIdentifier(node) {
		return !parameters[node.Text()]
	}
	if !ast.IsArrayBindingPattern(node) {
		return false
	}
	for _, element := range node.AsBindingPattern().Elements.Nodes {
		if !ast.IsBindingElement(element) || element.Initializer() != nil || element.AsBindingElement().DotDotDotToken != nil || !initialIterationBinding(element.Name(), parameters) {
			return false
		}
	}
	return true
}

func initialIterationExpression(node *ast.Node) bool {
	if initialReadExpression(node) {
		return true
	}
	node = identityPreservingUnwrap(node)
	if node == nil || !ast.IsCallExpression(node) || !initialReadExpression(node.Expression()) {
		return false
	}
	for _, argument := range node.AsCallExpression().Arguments.Nodes {
		if !initialReadExpression(argument) {
			return false
		}
	}
	return true
}

// This walk follows evaluation order only as far as the first identifier.
// Computed access, comma expressions, assignments and every other form stop it.
func initialCallReceiver(node *ast.Node) *ast.Node {
	node = identityPreservingUnwrap(node)
	if node == nil || !ast.IsCallExpression(node) {
		return nil
	}
	node = identityPreservingUnwrap(node.Expression())
	for node != nil {
		switch {
		case ast.IsIdentifier(node):
			return node
		case ast.IsPropertyAccessExpression(node), ast.IsCallExpression(node):
			node = identityPreservingUnwrap(node.Expression())
		default:
			return nil
		}
	}
	return nil
}

func initialReadExpression(node *ast.Node) bool {
	node = identityPreservingUnwrap(node)
	if node == nil {
		return false
	}
	if ast.IsIdentifier(node) {
		return true
	}
	return ast.IsPropertyAccessExpression(node) && initialReadExpression(node.Expression())
}

export function check(input: string) {
  var input = "local";
  const first = input.slice(0);
  input = "later";
  return first;
}

